import test from 'node:test';
import assert from 'node:assert/strict';
import {mkdtemp,readFile,writeFile,stat,readdir,symlink,rm} from 'node:fs/promises';
import {tmpdir} from 'node:os';
import path from 'node:path';
import {promisify} from 'node:util';
import {execFile} from 'node:child_process';
import {parseArgs,runCli} from '../src/dispatch.js';
import {CrewClient,CrewRequestError,saveConfig,readConfig} from '../src/client.js';
import {validateServerUrl,validateConfig} from '../src/config.js';
import {table,format,terminalText,displayWidth,truncateText} from '../src/output.js';
import {testServer} from '../../server/test/helpers.js';
const exec=promisify(execFile);
const bin=new URL('../bin/crew.js',import.meta.url).pathname;
test('explicit false and negated confirmation cannot become destructive consent',()=>{
  assert.equal(parseArgs(['issue','delete','x','--yes=false']).options.yes,false);
  assert.equal(parseArgs(['--no-yes','issue','delete','x']).options.yes,false);
  assert.equal(parseArgs(['--yes=true']).options.yes,true);
  assert.equal(parseArgs(['--preview=false','--no-json']).options.preview,false);
});
test('boolean syntax rejects ambiguous values and duplicate positive or negative options',()=>{
  for(const value of ['0','1','','FALSE','perhaps'])assert.throws(()=>parseArgs(['--yes='+value]),/true or false/);
  assert.throws(()=>parseArgs(['--yes','--no-yes']),/Duplicate/);
  assert.throws(()=>parseArgs(['--no-yes=true']),/does not accept/);
  assert.throws(()=>parseArgs(['--url=a','--url=b']),/Duplicate/);
});
test('valued options retain equals negative values and literal arguments after delimiter',()=>{
  const result=parseArgs(['issue','edit','id','--title=a=b','--priority','-1','--','--literal']);
  assert.equal(result.options.title,'a=b');assert.equal(result.options.priority,'-1');assert.deepEqual(result.args,['edit','id','--literal']);
  assert.throws(()=>parseArgs(['--__proto__=bad']),/Invalid/);
  assert.throws(()=>parseArgs(['--config']),/Missing/);
});
test('human output escapes terminal instructions newlines and bidirectional overrides',()=>{
  const dangerous='title\x1b]0;injected\x07\nsecond\u202e';
  const output=format({items:[{title:dangerous}],nextCursor:'next\rsegment'});
  assert(!/[\x00-\x09\x0b-\x1f\x7f\u202e]/.test(output));
  assert(output.includes('\\u001b'));assert(output.includes('\\u000a'));assert(output.includes('Next cursor: next\\u000dsegment'));
});
test('human columns preserve whole graphemes and account for CJK and emoji display widths',()=>{
  assert.equal(displayWidth('e\u0301'),1);assert.equal(displayWidth('团队'),4);assert.equal(displayWidth('👩‍💻'),2);
  assert.equal(truncateText('👩‍💻alpha',3),'👩‍💻…');assert.equal(truncateText('团队',3),'团…');
  const rows=table([{name:'团队',n:1},{name:'abcd',n:2}]).split('\n');
  assert.equal(displayWidth(rows[1].split('1')[0]),displayWidth(rows[2].split('2')[0]));
});
test('human lists expose later fields next cursors and zero totals without exposing secret columns',()=>{
  const output=format({items:[{id:'a',token:'private'},{id:'b',name:'later'}],total:0,nextCursor:'opaque'});
  assert(output.includes('name'));assert(output.includes('later'));assert(!output.includes('private'));
  assert(output.endsWith('Total: 0\nNext cursor: opaque'));
  assert.equal(table([{cookie:'secret'}]),'No displayable fields');
});
test('JSON output preserves original data and cursor structure',()=>{
  const value={items:[{title:'line\nnext',token:'copy-once'}],nextCursor:'opaque'};
  assert.deepEqual(JSON.parse(format(value,true)),value);assert.equal(terminalText('normal'),'normal');
});
test('config validates credential and origin shape before writing or sending',()=>{
  for(const url of ['file:///tmp/file','http:host','https://user:pass@host','https://host/?token=secret','https://host/#fragment','https://host/\n'])assert.throws(()=>validateServerUrl(url));
  assert.equal(validateServerUrl('http://localhost:4100/root/'),'http://localhost:4100/root');
  for(const value of [null,[],{token:1},{cookie:'line\nnext'},{cookie:'cookie',token:'token'}])assert.throws(()=>validateConfig(value));
});
test('credential replacement is atomic private and leaves no temporary file',async()=>{
  const folder=await mkdtemp(path.join(tmpdir(),'crew-config-'));
  try{
    const file=path.join(folder,'config.json');await writeFile(file,'{"token":"old"}',{mode:0o644});const before=await stat(file);
    await saveConfig({url:'http://localhost:4100',token:'new'},file);
    const after=await stat(file);assert.notEqual(after.ino,before.ino);assert.equal(after.mode&0o777,0o600);
    assert.equal((await readConfig(file)).token,'new');assert.deepEqual(await readdir(folder),['config.json']);
  }finally{await rm(folder,{recursive:true,force:true});}
});
test('config writer refuses symlink targets without changing referenced credentials',async()=>{
  const folder=await mkdtemp(path.join(tmpdir(),'crew-config-link-'));
  try{
    const real=path.join(folder,'real.json'),link=path.join(folder,'config.json');await writeFile(real,'original');await symlink(real,link);
    await assert.rejects(saveConfig({token:'new'},link),/regular file/);assert.equal(await readFile(real,'utf8'),'original');
    assert.equal((await readdir(folder)).length,2);
  }finally{await rm(folder,{recursive:true,force:true});}
});
test('config read distinguishes absent config malformed JSON and invalid schema',async()=>{
  const folder=await mkdtemp(path.join(tmpdir(),'crew-config-read-'));
  try{
    const file=path.join(folder,'config.json');assert.deepEqual(await readConfig(file),{});
    await writeFile(file,'{');await assert.rejects(readConfig(file),/Cannot read/);
    await writeFile(file,'[]');await assert.rejects(readConfig(file),/JSON object/);
  }finally{await rm(folder,{recursive:true,force:true});}
});
test('client preserves raw streaming response and upload duplex ownership',async()=>{
  const body=new ReadableStream({start(controller){controller.enqueue(new Uint8Array([1,2]));controller.close();}});
  let sent;const response=new Response(new Uint8Array([9,8]));
  const client=new CrewClient({token:'secret',fetcher:async(url,options)=>{sent={url,options};return response;}});
  assert.equal(await client.post('/attachments',body,{stream:true,response:true}),response);
  assert.equal(sent.options.body,body);assert.equal(sent.options.duplex,'half');assert.equal(sent.options.redirect,'manual');
  assert.equal(sent.options.headers.Authorization,'Bearer secret');assert(!sent.options.headers['Content-Type']);
});
test('client retains API error details and parses empty and binary responses',async()=>{
  const errorClient=new CrewClient({fetcher:async()=>Response.json({error:{code:'CONFLICT',message:'Changed',details:{revision:'new'}}},{status:409})});
  await assert.rejects(errorClient.patch('/issues/id',{}),error=>error instanceof CrewRequestError&&error.status===409&&error.details.revision==='new');
  const empty=new CrewClient({fetcher:async()=>new Response(null,{status:204})});assert.equal(await empty.delete('/items/id'),null);
  const binary=new CrewClient({fetcher:async()=>new Response(new Uint8Array([0,255]))});assert.deepEqual(await binary.get('/file',{binary:true}),Buffer.from([0,255]));
});
test('client classifies malformed JSON redirects and network failures without replay',async()=>{
  for(const [response,code] of [[()=>new Response('{',{headers:{'content-type':'application/json'}}),'INVALID_RESPONSE'],[()=>new Response(null,{status:302,headers:{location:'https://other.test'}}),'REDIRECT_REFUSED']]){
    let calls=0;const client=new CrewClient({fetcher:async()=>{calls++;return response();}});await assert.rejects(client.get('/me'),error=>error.code===code);assert.equal(calls,1);
  }
  const client=new CrewClient({fetcher:async()=>{throw new TypeError('private connection details');}});await assert.rejects(client.get('/me'),error=>error.code==='CONNECTION_FAILED'&&!error.message.includes('private'));
});
test('caller cancellation and deadline are classified without sending replacement requests',async()=>{
  const controller=new AbortController();controller.abort();
  const client=new CrewClient({fetcher:async(url,options)=>{options.signal.throwIfAborted();}});
  await assert.rejects(client.get('/me',{signal:controller.signal}),error=>error.code==='CANCELLED');
  await assert.rejects(client.get('/me',{timeoutMs:0}),/positive integer/);
});
test('credential-free command help does not read malformed config or contact a server',async()=>{
  const folder=await mkdtemp(path.join(tmpdir(),'crew-help-'));
  try{
    const config=path.join(folder,'broken');await writeFile(config,'broken');const lines=[];
    await runCli(['login','--help','--config',config],{write:text=>lines.push(text)});assert(lines[0].includes('CREW_PASSWORD'));
    await runCli(['help','--config',config],{write:text=>lines.push(text)});assert(lines[1].includes('Commands:'));
  }finally{await rm(folder,{recursive:true,force:true});}
});
test('actual CLI explicit false refuses deletion and logout revokes the stored browser session',async()=>{
  const server=await testServer();
  try{
    const request=server.agent();const signup=await request('POST','/auth/signup',{name:'CLI owner',email:'cli-safe@example.test',password:'long cli password'});
    const org=await request('POST','/orgs',{name:'Safe org'});const project=await request('POST','/orgs/'+org.data.organization.id+'/projects',{name:'Safe project',key:'SAFE'});
    const config=path.join(server.ctx.config.dataDir,'cli.json');await saveConfig({url:server.url,cookie:signup.cookie},config);
    await assert.rejects(exec(process.execPath,[bin,'project','delete',project.data.project.id,'--yes=false','--config',config],{timeout:5000}),error=>error.code===1&&error.stderr.includes('--yes'));
    assert.equal((await request('GET','/projects/'+project.data.project.id)).status,200);
    await exec(process.execPath,[bin,'logout','--config',config,'--json'],{timeout:5000});assert.equal((await readConfig(config)).cookie,undefined);
    assert.equal((await request('GET','/me')).status,401);
  }finally{await server.close();}
});
